const body = $json.body || {};
const action = body.action || 'event';
const sender = body.sender?.login || 'guitarist';
const repo = body.repository?.full_name || 'merx666/gryf-guitar';
const stars = body.repository?.stargazers_count || 0;

let message = '';
if (action === 'created' && body.starred_at) {
  message = `⭐ New Star on GitHub! ${sender} just starred ${repo}. Total stars: ${stars}`;
} else if (action === 'published' && body.release) {
  message = `🚀 NEW RELEASE: Gryf ${body.release.tag_name} is live!\n\n${body.release.body || 'Performance improvements and new rock songs.'}`;
} else {
  message = `🔔 GitHub Event: ${action} by ${sender} on ${repo}`;
}

return [{
  json: {
    timestamp: new Date().toISOString(),
    event: action,
    sender,
    stars,
    message
  }
}];
